# src/workpeg/__init__.py

__all__ = ["__version__"]

try:
    from importlib.metadata import version as _dist_version

    #: Read from the INSTALLED distribution rather than written here.
    #:
    #: This used to be a literal, and the literal said "0.1.0" in every wheel
    #: ever published — because `make release` stamps pyproject.toml and
    #: nothing stamped this. The distribution metadata was always right and
    #: this attribute was always wrong, which is the worst arrangement: a
    #: version that is present, plausible and false. `workpeg --version` was
    #: never affected only because cli.py had quietly grown its own copy of
    #: this lookup rather than importing the one that was broken.
    #:
    #: Deriving it removes the second thing to keep in step. There is nothing
    #: for a release to stamp here now, and nothing for a release to forget.
    __version__ = _dist_version("workpeg")
except Exception:  # pragma: no cover - a source tree with no dist installed
    # Not a version. A caller comparing this to anything gets a clean answer
    # rather than a number that happens to be wrong.
    __version__ = "unknown"
